import React from 'react';
import { TOOL_ARSENAL } from '../data';
import { Settings, Zap, Database, Brain } from 'lucide-react';

const Arsenal = () => {
  const getIcon = (name: string) => {
    if (name.includes('Models')) return <Brain size={24} className="text-brand-red" />;
    if (name.includes('Orchestration')) return <Settings size={24} className="text-brand-red" />;
    if (name.includes('Intelligence')) return <Zap size={24} className="text-brand-red" />;
    return <Database size={24} className="text-brand-red" />;
  };

  return (
    <div className="min-h-screen pt-32 pb-24 px-6 max-w-7xl mx-auto">
      <div className="mb-20 text-center">
        <h2 className="text-5xl md:text-7xl font-black tracking-tighter mb-6 uppercase">
          The Arsenal
        </h2>
        <p className="text-gray-500 max-w-2xl mx-auto text-lg">
          A curated stack of enterprise-grade tools. No fluff, just leverage. 
          Selected for reliability, scalability, and integration capabilities.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-12">
        {TOOL_ARSENAL.map((category) => (
          <div key={category.name} className="bg-white border-2 border-black p-8 relative shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] hover:translate-x-1 hover:translate-y-1 hover:shadow-none transition-all duration-200">
            <div className="flex items-center gap-4 mb-8 pb-4 border-b border-gray-100">
              {getIcon(category.name)}
              <h3 className="text-xl font-black uppercase tracking-wider">{category.name}</h3>
            </div>

            <div className="flex flex-wrap gap-3">
              {category.tools.map((tool) => (
                <div 
                  key={tool} 
                  className="group flex items-center gap-2 bg-gray-50 px-4 py-2 border border-gray-200 hover:border-black hover:bg-black transition-colors duration-200"
                >
                  <span className="w-1.5 h-1.5 bg-brand-red rounded-full"></span>
                  <span className="text-sm font-bold text-gray-700 group-hover:text-white uppercase tracking-wide">
                    {tool}
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Arsenal;

import React from 'react';
import { EXPERIENCES } from '../data';
import { GraduationCap, Briefcase, Code, Crown } from 'lucide-react';

const Journey = () => {
  const getIcon = (type: string) => {
    switch(type) {
      case 'education': return <GraduationCap size={20} />;
      case 'internship': return <GraduationCap size={20} />; 
      case 'work': return <Code size={20} />; 
      default: return <Briefcase size={20} />;
    }
  };

  return (
    <div className="min-h-screen pt-32 pb-24 px-6 bg-brand-black text-white">
       <div className="max-w-4xl mx-auto text-center mb-16">
        <h2 className="text-4xl md:text-6xl font-black tracking-tighter mb-4 text-white">The Evolution</h2>
        <p className="text-gray-400">From learning the ropes to architecting for Fortune 500s.</p>
      </div>

      <div className="max-w-3xl mx-auto relative">
        {/* Center Line */}
        <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-px bg-gray-800 transform md:-translate-x-1/2"></div>

        <div className="space-y-12">
          {EXPERIENCES.map((exp, index) => {
            const isEven = index % 2 === 0;
            const isLatest = index === 0;

            return (
              <div key={exp.id} className={`relative flex flex-col md:flex-row items-center ${isEven ? 'md:flex-row-reverse' : ''}`}>

                {/* Timeline Dot/Icon */}
                <div className="absolute left-4 md:left-1/2 w-10 h-10 rounded-full bg-black border-2 border-gray-700 flex items-center justify-center z-10 transform -translate-x-1/2">
                   {isLatest ? <Crown size={16} className="text-brand-red" /> : getIcon(exp.type)}
                </div>

                {/* Content Spacer */}
                <div className="hidden md:block w-1/2"></div>

                {/* Content Card */}
                <div className={`w-full md:w-1/2 pl-12 md:pl-0 ${isEven ? 'md:pr-12 md:text-right' : 'md:pl-12 md:text-left'}`}>
                  <div className={`p-6 rounded-lg border transition-colors duration-300 ${
                    isLatest 
                      ? 'bg-black border-green-900 shadow-[0_0_30px_rgba(0,255,0,0.1)]' 
