                    <span className="block text-[10px] font-mono text-gray-500 mb-2 uppercase tracking-widest">
                      {exp.period}
                    </span>
                    <h3 className="text-2xl font-black text-white mb-1">
                      {exp.company}
                    </h3>

                    <div className={`inline-block px-2 py-0.5 mb-4 text-[10px] font-bold uppercase tracking-wider rounded ${
                      isLatest ? 'bg-green-900/30 text-green-500' : 'bg-gray-800 text-gray-400'
                    }`}>
                      {exp.role}
                    </div>

                    <p className="text-sm text-gray-400 leading-relaxed">
                      {exp.description}
                    </p>

                    {isLatest && (
                       <div className="mt-4 flex items-center justify-end gap-2 text-[10px] font-bold text-green-500 uppercase tracking-widest animate-pulse">
                          Visit HQ <span className="text-lg">→</span>
                       </div>
